// StableHLO program implementing the forward pass of the described PyTorch model
// Arguments:
// %arg0: bias tensor of shape [6, 1, 1]
// %arg1: convolution weight tensor of shape [6, 7, 3, 3]
// %arg2: convolution bias tensor of shape [6]
// %arg3: input tensor of shape [6, 7, 6, 6]
// Returns:
// tensor<6x6x4x4xf32> output after conv + relu + bias addition

func.func @main(%arg0: tensor<6x1x1xf32>, 
               %arg1: tensor<6x7x3x3xf32>, 
               %arg2: tensor<6xf32>, 
               %arg3: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // Step 1: Perform convolution
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[2, 3, 1, 2] -> [b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Step 2: Apply ReLU (element-wise exponential of zero minus the input, then subtract from zero to get relu)
  // Alternatively, use 'abs' and 'maximum' with zero, but since only relu is needed, use 'stablehlo.maximum' with zero
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %relu = "stablehlo.maximum"(%conv, %zero) : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x4x4xf32>

  // Step 3: Broadcast bias to match convolution output shape
  // %arg0 shape: [6,1,1], need to broadcast to [6,6,4,4]
  %bcast_bias = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = array<i64: 0, 1, 2>
  } : (tensor<6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // Step 4: Add bias
  %add_bias = "stablehlo.add"(%relu, %bcast_bias) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  // Return the result
  return %add_bias : tensor<6x6x4x4xf32>
}
