  func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<6x7x3x3xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
