    %conv = "stablehlo.convolution"(%arg3, %arg1) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

    // Step 2: ReLU activation
    // ReLU = max(0, x)
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %relu = "stablehlo.maximum"(%conv, %zero) : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x4x4xf32>

    // Step 3: Add bias
    // %arg2 is bias of shape (6), need to broadcast to match %relu shape
    // First, broadcast bias to shape (6,1,1)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<6xf32>) -> tensor<6x1x1xf32>

    // Then, broadcast bias to shape (6,6,4,4)
    // broadcast_dimensions for bias: [0, 1, 2, 3]
    // bias shape: (6), target shape: (6,6,4,4)
    %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%bias_broadcast) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<6x1x1xf32>) -> tensor<6x6x4x4xf32>

    // Add bias to relu output
    %output = "stablehlo.add"(%relu, %bias_broadcast2) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

    // Return the result
    return %output : tensor<6x6x4x4xf32>
  }
